/**
 * Build-time generation of a source's adapter manifest (`<source>/manifest.json`): every command's metadata, so the
 * runtime can list and search a read-only source without importing its modules (see SiteRegistry). Generated by
 * `npm run build` for the built-in corpus; tests/adapter-manifest.test.ts fails if the committed file drifts.
 */
import fs from 'node:fs';
import path from 'node:path';
import { isDeepStrictEqual } from 'node:util';
import { pathToFileURL } from 'node:url';
import { ADAPTER_MANIFEST_FILE, ADAPTER_MANIFEST_FORMAT, adapterCommandFromDescriptor, adapterMetadata, type AdapterManifest } from './loader.js';

const byName = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

/** Import and validate every command in `dir`; throws on any adapter that would fail to load at runtime. */
export async function generateAdapterManifest(dir: string): Promise<AdapterManifest> {
  const sites: AdapterManifest['sites'] = {};
  const siteNames = fs.readdirSync(dir).filter((d) => !d.startsWith('.') && fs.statSync(path.join(dir, d)).isDirectory()).sort(byName);
  for (const site of siteNames) {
    const commands: AdapterManifest['sites'][string] = {};
    for (const file of fs.readdirSync(path.join(dir, site)).filter((f) => f.endsWith('.js') && !f.startsWith('_')).sort(byName)) {
      const name = file.replace(/\.js$/, '');
      const location = `${site}/${file}`;
      const mod = await import(pathToFileURL(path.join(dir, site, file)).href) as { default?: Record<string, unknown> };
      if (!mod.default || typeof mod.default.run !== 'function') throw new Error(`${location} must \`export default defineAdapter({...})\``);
      let meta;
      try { meta = adapterMetadata(adapterCommandFromDescriptor(site, name, 'builtin', mod.default)); }
      catch (err) { throw new Error(`${location}: ${(err as Error).message}`); }
      // The manifest is JSON: metadata that JSON cannot carry would be described differently than the module declares.
      const stored = JSON.parse(JSON.stringify(meta)) as typeof meta;
      for (const key of Object.keys(meta) as Array<keyof typeof meta>) if (meta[key] === undefined) delete meta[key];
      if (!isDeepStrictEqual(stored, meta)) throw new Error(`${location}: descriptor metadata must be plain JSON (no functions, RegExps, undefined members or non-finite numbers)`);
      commands[name] = stored;
    }
    if (Object.keys(commands).length) sites[site] = commands;
  }
  return { format: ADAPTER_MANIFEST_FORMAT, sites };
}

export function renderAdapterManifest(manifest: AdapterManifest): string {
  return `${JSON.stringify(manifest, null, 2)}\n`;
}

export function manifestPath(dir: string): string { return path.join(dir, ADAPTER_MANIFEST_FILE); }
